# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAKARA SURESİ 187-210. AYETLERDE TECVİT UYGULAMALARI (KK.7.2.3)</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Sakin Mimin 3 Hâli (مْ)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• İhfa-i Şefevî (مْ + ب):</text>\n  <text x="40" y="114" font-size="10.5" fill="#475569">  Dudak ihfası, gunneli okunur</text>\n  <text x="40" y="138" font-size="11" fill="#334155">• İdgam-ı Misleyn Meal-Gunne</text>\n  <text x="40" y="154" font-size="10.5" fill="#475569">  (مْ + م): لَكُمْ مَا كَسَبْتُمْ</text>\n  <text x="40" y="178" font-size="11" fill="#334155">• İzhar-ı Şefevî (مْ + 26 harf):</text>\n  <text x="40" y="194" font-size="10.5" fill="#475569">  أَمْوَالَكُمْ بَيْنَكُمْ / عَلَيْكُمْ</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İdgam-ı Misleyn Çeşitleri</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Meal-Gunne (Gunneli):</text>\n  <text x="260" y="114" font-size="10.5" fill="#475569">  Sakin مْ→م veya sakin نْ→ن</text>\n  <text x="260" y="132" font-size="10.5" fill="#166534">  Örn: مَنْ نَشَاءُ / لَكُمْ مَا</text>\n  <text x="260" y="158" font-size="11" fill="#334155">• Bila-Gunne (Gunnesiz):</text>\n  <text x="260" y="174" font-size="10.5" fill="#475569">  م ve ن dışındaki aynı iki harf</text>\n  <text x="260" y="192" font-size="10.5" fill="#166534">  Örn: فَمَا رَبِحَتْ تِجَارَتُهُمْ (تْ+ت)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Diğer Tecvit Kuralları</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Medd-i Muttasıl / Munfasıl:</text>\n  <text x="480" y="114" font-size="10.5" fill="#475569">  آتِنَا فِي الدُّنْيَا / أُولٰئِكَ</text>\n  <text x="480" y="138" font-size="11" fill="#334155">• Kalkale (ق ط ب ج د):</text>\n  <text x="480" y="154" font-size="10.5" fill="#475569">  الْحَجِّ / بِالْحَقِّ / خَلَاقٍ</text>\n  <text x="480" y="178" font-size="11" fill="#334155">• Lafzatullah (اللّٰه) ve Ra (ر):</text>\n  <text x="480" y="194" font-size="10.5" fill="#475569">  وَاتَّقُوا اللّٰهَ (kalın) · لِلّٰهِ (ince)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YENİDEN DİRİLME KISSASI: BAKARA SURESİ 259. AYET (KK.7.2.4)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Kıssadaki Olay Örgüsü (Bakara 259)</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Salih bir kul (Hz. Üzeyir) çatıları çökmüş,</text>\n  <text x="44" y="114" font-size="11" fill="#334155">  ıssız bir şehrin yanından geçer.</text>\n  <text x="44" y="136" font-size="11" fill="#334155">• Hayretle sorar: "أَنَّى يُحْيِي هٰذِهِ اللّٰهُ بَعْدَ مَوْتِهَا"</text>\n  <text x="44" y="152" font-size="10.5" fill="#1e40af">  (Allah burayı ölümünden sonra nasıl diriltir?)</text>\n  <text x="44" y="174" font-size="11" fill="#334155">• Allah onu 100 YIL (مِائَةَ عَامٍ) öldürür (uyutur),</text>\n  <text x="44" y="190" font-size="11" fill="#334155">  sonra tekrar diriltir (ثُمَّ بَعَثَهُ).</text>\n  <text x="44" y="212" font-size="11" fill="#334155">• "Bir gün veya günün bir kısmı kaldım" sanır.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Üç İlahi Kanıt (Delil) ve İkrar</text>\n  <text x="378" y="98" font-size="11" fill="#334155">1. Yiyecek ve İçecek: 100 yıl geçtiği hâlde</text>\n  <text x="378" y="114" font-size="11" fill="#334155">   bozulmamıştır (لَمْ يَتَسَنَّهْ).</text>\n  <text x="378" y="138" font-size="11" fill="#334155">2. Merkebi (حِمَارِكَ): Çürümüş kemikler hâlindedir;</text>\n  <text x="378" y="154" font-size="11" fill="#334155">   gözünün önünde kemikler birleşip et giydirilir.</text>\n  <text x="378" y="178" font-size="11" fill="#334155">3. Sonuç ve İkrar: "أَعْلَمُ أَنَّ اللّٰهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ"</text>\n  <text x="378" y="196" font-size="10.5" font-weight="bold" fill="#92400e">   (Biliyorum ki Allah her şeye kadirdir!)</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">Anahtar Kavram: البَعْثُ (Ba\'s = Ölümden sonra diriliş)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. İBRAHİM\'İN (AS) DİRİLİŞİ GÖZLEMLEMESİ: BAKARA 260. AYET</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Hz. İbrahim\'in (as) Dua ve İsteği</text>\n  <text x="44" y="100" font-size="11.5" font-weight="bold" fill="#166534">"رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى"</text>\n  <text x="44" y="120" font-size="11" fill="#334155">(Rabbim! Ölüleri nasıl dirilttiğini bana göster!)</text>\n  <text x="44" y="146" font-size="11" fill="#334155">• Yüce Allah sorar: "أَوَلَمْ تُؤْمِنْ؟" (İnanmadın mı?)</text>\n  <text x="44" y="168" font-size="11.5" font-weight="bold" fill="#166534">• Hz. İbrahim: "بَلَى وَلٰكِنْ لِيَطْمَئِنَّ قَلْبِي"</text>\n  <text x="44" y="188" font-size="11" fill="#334155">  (Hayır inandım, fakat KALBİM MUTMAİN OLSUN</text>\n  <text x="44" y="204" font-size="11" fill="#334155">  / gönlüm huzur ve yakîn bulsun diye!)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Dört Kuş Mucizesi ve İbretler</text>\n  <text x="378" y="100" font-size="11" fill="#334155">• Allah buyurur: "أَرْبَعَةً مِنَ الطَّيْرِ" (Dört kuş al,</text>\n  <text x="378" y="118" font-size="11" fill="#334155">  kendine alıştır, sonra parçalayıp her dağın</text>\n  <text x="378" y="136" font-size="11" fill="#334155">  başına birer parçasını koy).</text>\n  <text x="378" y="160" font-size="11" fill="#334155">• "ثُمَّ ادْعُهُنَّ يَأْتِينَكَ سَعْيًا" (Sonra onları çağır;</text>\n  <text x="378" y="178" font-size="11" fill="#334155">  koşarak/uçarak sana gelirler!)</text>\n  <text x="378" y="204" font-size="11" font-weight="bold" fill="#9d174d">• Mesaj: Allah Azîz\'dir (mutlak güç sahibi)</text>\n  <text x="378" y="220" font-size="11" font-weight="bold" fill="#9d174d">  ve Hakîm\'dir (her işi hikmetli olan).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
